CREATE OR REPLACE FUNCTION cf_user_guards_v1.acquire_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_LEVEL<>'STATEMENT' OR TG_RELID NOT IN ('public.profiles'::regclass,'public.user_roles'::regclass,'public.user_clientes'::regclass,'public.partner_users'::regclass,'auth.users'::regclass) THEN RAISE EXCEPTION 'invalid_user_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $function$

platform_private.delivery_mutation_guard.definition:
CREATE OR REPLACE FUNCTION platform_private.delivery_mutation_guard_20261030()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.delivery_context_20261030%ROWTYPE; v_org uuid;
 v_proof text[]:=ARRAY['comprovante_status','assinatura_tipo','recebedor_nome','recebedor_documento','recebedor_cargo','recebedor_telefone','comprovante_anexado_em','comprovante_anexado_por','assinatura_digital_capturada_em','assinatura_digital_capturada_por','comprovante_id','formulario_gerado_em','formulario_gerado_por','validation_token','validation_hash','updated_at'];
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM platform_private.delivery_context_20261030
 WHERE txid=pg_catalog.txid_current() AND actor=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='proof' THEN
  v_org:=platform_private.delivery_proof_actor_20261030();
  IF TG_OP='UPDATE' AND c.mutation='proof' AND c.organization_id=v_org AND NEW.id=c.target AND OLD.id=c.target
  AND OLD.organization_id=v_org AND NEW.organization_id=v_org
  AND OLD.partner_order_id IS NULL AND NEW.partner_order_id IS NULL
  AND OLD.ordem_servico_onfarm_id IS NULL AND NEW.ordem_servico_onfarm_id IS NULL
  AND NEW.status=OLD.status AND NEW.receivable_id IS NOT DISTINCT FROM OLD.receivable_id
  AND (pg_catalog.to_jsonb(NEW)-v_proof) IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-v_proof) THEN
   UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
   RETURN NEW;
  END IF;
  RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501';
 END IF;
 v_org:=platform_private.delivery_actor_20261030(c.action);
 IF c.organization_id IS DISTINCT FROM v_org OR NEW.organization_id IS DISTINCT FROM v_org
 OR NEW.partner_order_id IS NOT NULL OR NEW.receivable_id IS NOT NULL OR NEW.ordem_servico_onfarm_id IS NOT NULL
 THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='group' AND TG_OP='INSERT' AND c.mutation='create' AND c.delivery IS NULL
 AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item AND NEW.status::text='separado' THEN
  UPDATE platform_private.delivery_context_20261030 SET delivery=NEW.id,mutation='decorate' WHERE txid=c.txid;
 ELSIF c.action='group' AND TG_OP='UPDATE' AND c.mutation='decorate' AND NEW.id=c.delivery
 AND OLD.id=c.delivery AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item
 AND NEW.organization_id=OLD.organization_id AND NEW.status=OLD.status THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSIF c.action='cancel' AND TG_OP='UPDATE' AND c.mutation='cancel' AND NEW.id=c.target AND OLD.id=c.target
 AND OLD.organization_id=v_org AND NEW.status::text='cancelada' AND NEW.financial_status='CANCELED'
 AND (pg_catalog.to_jsonb(NEW)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status'])
 IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status']) THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSE RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

platform_private.partner_order_items_cat.definition:
CREATE OR REPLACE FUNCTION platform_private.partner_order_items_catalog_tenant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_t uuid;
BEGIN
  IF NOT (NEW.product_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF true THEN
    v_t := (SELECT pa.commercial_owner_organization_id FROM public.partner_accounts pa WHERE pa.id = (SELECT po.partner_id FROM public.partner_orders po WHERE po.id = NEW.order_id));
    IF NEW.product_id IS NOT NULL AND (v_t IS NULL OR NOT EXISTS (SELECT 1 FROM public.produtos z WHERE z.id = NEW.product_id AND z.owner_organization_id = v_t)) THEN
      RAISE EXCEPTION 'tenant_catalog_cross_tenant_reference' USING ERRCODE = '42501', DETAIL = 'partner_order_items.product_id'; END IF;
    IF NEW.microrganismo_id IS NOT NULL AND (v_t IS NULL OR NOT EXISTS (SELECT 1 FROM public.microrganismos z WHERE z.id = NEW.microrganismo_id AND z.owner_organization_id = v_t)) THEN
      RAISE EXCEPTION 'tenant_catalog_cross_tenant_reference' USING ERRCODE = '42501', DETAIL = 'partner_order_items.microrganismo_id'; END IF;
  END IF;
  RETURN NEW;
END $function$

platform_private.solid_pack_presentation.definition:
CREATE OR REPLACE FUNCTION platform_private.solid_pack_presentation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_forma text; v_ticket boolean;
BEGIN
  v_ticket := EXISTS (SELECT 1 FROM platform_private.solid_pack_presentation_tx t WHERE t.txid = pg_catalog.txid_current());
  IF TG_OP = 'DELETE' THEN
    IF OLD.medida = 'embalagem' THEN RAISE EXCEPTION 'PRESENTATION_HISTORY' USING ERRCODE='42501'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.medida IS DISTINCT FROM OLD.medida THEN
    RAISE EXCEPTION 'PRESENTATION_MEDIDA_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF NEW.medida = 'embalagem' THEN
    IF v_ticket IS NOT TRUE THEN RAISE EXCEPTION 'PRESENTATION_PACK_WRITER_ONLY' USING ERRCODE='42501'; END IF;
    IF TG_OP = 'UPDATE' AND (NEW.produto_id, NEW.owner_organization_id, NEW.rotulo, NEW.item_tipo)
         IS DISTINCT FROM (OLD.produto_id, OLD.owner_organization_id, OLD.rotulo, OLD.item_tipo) THEN
      RAISE EXCEPTION 'PRESENTATION_PACK_IMMUTABLE' USING ERRCODE='42501'; END IF;
  END IF;
  IF NEW.produto_id IS NOT NULL AND NEW.ativo IS TRUE THEN








    PERFORM 1 FROM public.produtos z WHERE z.id = NEW.produto_id FOR NO KEY UPDATE;
    SELECT s.forma_fisica INTO v_forma FROM public.product_sale_units s WHERE s.product_id = NEW.produto_id;
    IF (NEW.medida = 'volume' AND v_forma = 'solido') OR (NEW.medida = 'embalagem' AND v_forma IS DISTINCT FROM 'solido') THEN
      RAISE EXCEPTION 'PRESENTATION_MEDIDA_MISMATCH' USING ERRCODE='PT409'; END IF;
  END IF;
  RETURN NEW;
END $function$

platform_private.stock_envase_reservatio.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_envase_reservation_root_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.programacao_producao%ROWTYPE; l public.lotes%ROWTYPE; o public.ordens_servico%ROWTYPE;
BEGIN
 IF NEW.status::text<>'reservado' OR NEW.reservado_para_os_tipo IS DISTINCT FROM 'manual' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.lote_id IS NOT DISTINCT FROM OLD.lote_id AND NEW.reservado_para_os_id IS NOT DISTINCT FROM OLD.reservado_para_os_id THEN RETURN NEW; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=NEW.reservado_para_os_id;
 SELECT * INTO p FROM public.programacao_producao WHERE ordem_servico_id=o.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO l FROM public.lotes WHERE id=NEW.lote_id;
 IF o.status::text NOT IN ('em_cq','envase','pronto_entrega') OR l.programacao_id IS DISTINCT FROM p.id OR l.organization_id IS DISTINCT FROM o.organization_id OR p.organization_id IS DISTINCT FROM o.organization_id
 OR NEW.produto_id IS DISTINCT FROM p.produto_id OR NEW.microrganismo_id IS DISTINCT FROM p.microrganismo_id OR NEW.reservado_para_cliente_id IS DISTINCT FROM o.cliente_id
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=o.id)<>1 THEN RAISE EXCEPTION 'ENVASE_RESERVATION_LINEAGE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

platform_private.tenant_catalog_fence(te.definition:
CREATE OR REPLACE FUNCTION platform_private.tenant_catalog_fence(p_mode text, p_orgs uuid[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid;
BEGIN
  IF p_mode NOT IN ('mutate','read_catalog') THEN RAISE EXCEPTION 'tenant_catalog_fence_mode' USING ERRCODE='22023'; END IF;
  IF auth.uid() IS NULL THEN
    IF session_user::text IN ('anon','authenticated') OR current_setting('role', true) IN ('anon','authenticated') THEN
      RAISE EXCEPTION 'tenant_catalog_fence_denied' USING ERRCODE='42501'; END IF;
    RETURN;   -- contexto servidor sem ator (gatilho/serviço); clientes sempre têm auth.uid()
  END IF;
  BEGIN
    v_actor := platform_private.catalog_tenant_actor(p_mode);
  EXCEPTION WHEN raise_exception OR insufficient_privilege OR invalid_parameter_value THEN
    RAISE EXCEPTION 'tenant_catalog_fence_denied' USING ERRCODE='42501';
  END;
  IF v_actor IS NULL OR EXISTS (SELECT 1 FROM unnest(p_orgs) o WHERE o IS DISTINCT FROM v_actor) THEN
    RAISE EXCEPTION 'tenant_catalog_fence_denied' USING ERRCODE='42501'; END IF;
END $function$

public.set_codigo_microrganismo().definition:
CREATE OR REPLACE FUNCTION public.set_codigo_microrganismo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_prefixo text;
BEGIN
  IF NEW.owner_organization_id IS NULL THEN
    RETURN NEW;  -- sem dono não há sequência; RLS (WITH CHECK) / NOT NULL rejeitam a linha — o gerador não autoriza
  END IF;
  IF NEW.codigo IS NULL OR btrim(NEW.codigo) = '' THEN
    v_prefixo := public.prefixo_para_microrganismo(NEW.tipo::text);
    IF v_prefixo IS NULL THEN
      RAISE EXCEPTION 'Tipo de microrganismo sem prefixo definido: %', NEW.tipo;
    END IF;
    NEW.codigo := platform_private.tenant_proximo_codigo(NEW.owner_organization_id, v_prefixo, 'microrganismos');
  ELSE
    NEW.codigo := btrim(NEW.codigo);
  END IF;
  RETURN NEW;
END;
$function$

